module logic;
use model {Summary};
use util {reverse};
record Cursor {offset:I64,frames:List<Bytes>,error:I64,done:Bool}

fn run(data:Bytes,limit:I64)->Summary {
 let final=while(state:Cursor=Cursor {offset:0,frames:List::empty<Bytes>(),error:0,done:false}; !state.done && state.offset<Bytes::length(data)) {
  let n=Bytes::at(data,state.offset);
  if n>limit {
   Cursor {offset:state.offset,frames:state.frames,error:3,done:true}
  } else {
   if state.offset+1+n+1>Bytes::length(data) {
    Cursor {offset:state.offset,frames:state.frames,error:1,done:true}
   } else {
    let payload=Bytes::slice(data,state.offset+1,n);
    let sum=fold(i in n,total:I64=0) {total+Bytes::at(payload,i)};
    let checksum=Bytes::at(data,state.offset+1+n);
    if sum%256!=checksum {
     Cursor {offset:state.offset,frames:state.frames,error:2,done:true}
    } else {
     Cursor {offset:state.offset+1+n+1,frames:List::prepend(payload,state.frames),error:0,done:false}
    }
   }
  }
 };
 Summary {frames:reverse(final.frames),consumed:final.offset,error:final.error}
}
